#!/usr/bin/env python3
"""Builds docs/HERO_TREES.html: the page generated by HeroTreesDump (placeholder @@IDEAS@@) + docs/HERO_IDEAS.md rendered to HTML.
usage: PYTHONPATH=/tmp/pylib python3 tools/build_hero_html.py <page-with-placeholder.html> <out.html>   (pip install --target /tmp/pylib markdown)"""
import re, sys, markdown
page, out = sys.argv[1], sys.argv[2]
md = open('docs/HERO_IDEAS.md', encoding='utf-8').read()
md = re.sub(r'^# .*\n', '', md, count=1)
md = md.replace('(см. `HERO_TREES_MOD.md`)', '(см. разделы «Партии» и «Диктаторы фракций» ниже)')
a = md.find('Что проверено, а что нет')
b = md.find('Правило, чтобы идеи не были')
tech = md[a:b]
rest = md[:a] + '\n\n<div>@@TECH@@</div>\n\n' + md[b:]
html = markdown.markdown(rest, extensions=['tables'])
tech_html = '<details><summary><b>Технические подробности для реализации</b> (имена свойств игры, что проверено, а что нет)</summary>' + markdown.markdown(tech, extensions=['tables']) + '</details>'
html = html.replace('<div>@@TECH@@</div>', tech_html)
s = open(page, encoding='utf-8').read().replace('@@IDEAS@@', html)
open(out, 'w', encoding='utf-8').write(s)
print('ok', len(s))
